def compute(vars):
    allowance_percent = -vars["v1"] / vars["v2"] * 100
    return {
        "value": allowance_percent,
        "trace": {
            "allowance_magnitude": -vars["v1"],
            "trade_receivables": vars["v2"],
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
